<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to rewrite:
<original_code>
#include <iostream>
#include <algorithm>
#include <vector>
#include <string>
#define INF 100000000
using namespace std;
long long int fn,fd;
long long int ra,rb;
long long int gcd(long long int a, long long int b)
{
    if (b==0)
        return a;
    else
        return gcd(b,a%b);
}
//this is a void fucnction 

void function (long long int x, long long int y, long long int b, long long int a)
{
    if (a < 0) {
        return;
    }
    long long int kkk = gcd (a, b);
    a = a / kkk;     b = b/kkk;
    long long int kk,g,n,d;
    n = abs(b*x - a*y);
    d = b*y;
    g = gcd (n, d);
    n = n/g;    d = d/g;
    //cout << x << " " << y << " " << a << " " << b << endl;
    if (n*fd < fn*d) {
        fn = n;
        fd = d;
        ra = a;
        rb = b;
        return;
    }
    if (n*fd == d*fn) {
        if (b < rb) {
            ra = a;
            rb = b;
            return;
        }
        if (b > rb) {
            return;
        }
        if (a < ra) {
            ra = a;
            rb = b;
            return;
        }
    }
}
int main()
{
    fn = 100000;    fd = 1;
    long long int x,i,y,n;
    cin >> x >> y >> n;
    int j;
    for ( int i = 0; i < 19; i++ ) {
        j = i;
    }
    for (i = 1; i <= n; i++) {
        function (x, y, i, (i*x)/y);
        function (x, y, i, (i*x)/y + 1);
        function (x, y, i, (i*x)/y - 1);
    }
    cout << ra << "/" << rb << endl;
    return 0;
}
